{
  "skill": {
    "name": "wechat-md-publisher",
    "version": "0.8.15",
    "enabled": true,
    "autoInvoke": false
  },
  "commands": {
    "publish": {
      "script": "./scripts/publish.sh",
      "args": ["publish"],
      "description": "发布文章到微信公众号"
    },
    "draft": {
      "script": "./scripts/publish.sh",
      "args": ["draft"],
      "description": "创建微信公众号草稿"
    },
    "wrapper": {
      "script": "./scripts/publish.sh",
      "args": ["wrapper"],
      "description": "Wrapper 功能管理（文章开头/结尾固定图文）"
    },
    "list-drafts": {
      "script": "./scripts/publish.sh",
      "args": ["list-drafts"],
      "description": "列出所有草稿"
    },
    "list-published": {
      "script": "./scripts/publish.sh",
      "args": ["list-published"],
      "description": "列出已发布文章"
    },
    "themes": {
      "script": "./scripts/publish.sh",
      "args": ["themes"],
      "description": "列出可用主题"
    }
  },
  "environment": {
    "required": [
      "NODE_VERSION>=18.0.0",
      "WECHAT_APP_ID",
      "WECHAT_APP_SECRET"
    ],
    "optional": []
  },
  "dependencies": {
    "npm": [
      "wechat-md-publisher@0.8.8",
      "jsdom@^27.4.0",
      "form-data-encoder@^4.1.0",
      "formdata-node@^6.0.3"
    ]
  },
  "permissions": {
    "filesystem": {
      "read": ["*.md", "*.jpg", "*.png", "*.gif"],
      "write": ["~/.config/wechat-md-publisher-nodejs/"]
    },
    "network": {
      "domains": ["api.weixin.qq.com", "mp.weixin.qq.com"]
    }
  }
}

{
  "skill": {
    "name": "wechat-md-publisher",
    "displayName": "WeChat MD Publisher",
    "version": "0.8.15",
    "description": "全功能微信公众号 Markdown 发布工具 - 支持草稿、发布、删除和多主题。⚠️ 需要 WECHAT_APP_ID 和 WECHAT_APP_SECRET 环境变量",
    "requiredEnvVars": ["WECHAT_APP_ID", "WECHAT_APP_SECRET"],
    "envVars": {
      "required": ["WECHAT_APP_ID", "WECHAT_APP_SECRET"],
      "optional": []
    },
    "author": {
      "name": "Ping Si",
      "email": "sipingme@gmail.com",
      "github": "sipingme"
    },
    "repository": {
      "type": "git",
      "url": "https://github.com/sipingme/wechat-md-publisher-skill"
    },
    "license": "Apache-2.0",
    "category": "publishing",
    "tags": [
      "wechat",
      "publishing",
      "markdown",
      "content-management",
      "social-media"
    ],
    "requirements": {
      "node": ">=18.0.0",
      "npm": ">=8.0.0",
      "os": ["darwin", "linux", "win32"],
      "env": {
        "required": [
          {
            "name": "WECHAT_APP_ID",
            "description": "微信公众号 AppID（必需）"
          },
          {
            "name": "WECHAT_APP_SECRET",
            "description": "微信公众号 AppSecret（必需）"
          }
        ]
      }
    },
    "credentials": {
      "primary": "WECHAT_APP_SECRET",
      "storage": {
        "location": "~/.config/wechat-md-publisher-nodejs/",
        "handler": "wechat-md-publisher npm 包",
        "handlerRepo": "https://github.com/sipingme/wechat-md-publisher",
        "note": "凭证加密由上游 npm 包处理，本 skill 不直接处理凭证存储"
      }
    },
    "features": [
      "完整的草稿和发布管理",
      "8 个精美内置主题",
      "智能图片处理和缓存",
      "多账号支持",
      "CLI 工具和编程 API"
    ],
    "documentation": {
      "readme": "https://github.com/sipingme/wechat-md-publisher-skill/blob/main/README.md",
      "skill": "https://github.com/sipingme/wechat-md-publisher-skill/blob/main/SKILL.md",
      "quickStart": "https://github.com/sipingme/wechat-md-publisher-skill/blob/main/references/quick-start.md"
    },
    "screenshots": [],
    "demo": {
      "video": "",
      "gif": ""
    },
    "rating": {
      "clarity": 5,
      "timeToSuccess": 5,
      "usefulness": 5,
      "security": 5
    }
  }
}
